int n1 = mid - left + 1;
int n2 = right - mid;

T* leftArr = new T[n1];
T* rightArr = new T[n2];

for (int i = 0; i < n1; i++)
    leftArr[i] = arr[left + i];
for (int j = 0; j < n2; j++)
    rightArr[j] = arr[mid + 1 + j];

int i = 0, j = 0, k = left;

while (i < n1 && j < n2) {
    if (leftArr[i] <= rightArr[j]) {
        arr[k] = leftArr[i];
        i++;
    } else {
        arr[k] = rightArr[j];
        j++;
    }
    k++;
}

while (i < n1) {
    arr[k] = leftArr[i];
    i++;
    k++;
}

while (j < n2) {
    arr[k] = rightArr[j];
    j++;
    k++;
}

delete[] leftArr;
delete[] rightArr;

